import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.select.Elements;

import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.parsers.ParserConfigurationException;
import javax.xml.transform.Transformer;
import javax.xml.transform.TransformerException;
import javax.xml.transform.TransformerFactory;
import javax.xml.transform.dom.DOMSource;
import javax.xml.transform.stream.StreamResult;
import java.io.File;
import java.util.ArrayList;
import java.util.List;

public class XmlProcessor {

    public static void main(String[] args) throws Exception {
        // Parse the XML file
        Document document = Jsoup.parse(new File("person.xml").readAllBytes());

        // Extract data from the XML elements
        Elements persons = document.select("person");
        List<Person> people = new ArrayList<>();
        for (Element person : persons) {
            String name = person.selectFirst("name").text();
            int age = Integer.parseInt(person.selectFirst("age").text());
            people.add(new Person(name, age));
        }

        // Process the data
        for (Person person : people) {
            System.out.println("Name: " + person.getName());
            System.out.println("Age: " + person.getAge());
            System.out.println();
        }
    }
}

class Person {
    private String name;
    private int age;

    public Person(String name, int age) {
        this.name = name;
        this.age = age;
    }

    public String getName() {
        return name;
    }

    public int getAge() {
        return age;
    }
}
